public sealed class Order
{
    public OrderId Id { get; }
    public CustomerId Customer { get; }
    private Order(OrderId id, CustomerId customer) { Id = id; Customer = customer; }
    public static Order FromCart(Cart cart)
    {
        if (cart.Items.Count == 0) throw new DomainException("empty cart");
        return new Order(OrderId.New(), cart.CustomerId);
    }
    internal static Order Rehydrate(OrderId id, CustomerId customer) => new(id, customer);
}

