public static class OrderFactoryRegistration
{
    public static IServiceCollection AddOrderFactory(this IServiceCollection services) =>
        services.AddTransient<Func<Cart, Order>>(sp =>
        {
            var clock = sp.GetRequiredService<IClock>();
            return cart => Order.FromCart(cart, clock.UtcNow);
        });
}
